import{buildHeart}from './heart-anatomy.js?v=20261023-physicscomplete01';
export function buildCirculation(group,T,kind,w={}){
 const mat=(color,more={})=>new T.MeshStandardMaterial({color,roughness:.32,...more});
 if(kind==='heart'){buildHeart(group,T,w);return;}
 if(kind==='vessels'){
  const thickness=w.wall==='thick'?.25:w.wall==='one'?.035:.1,r=w.lumen==='large'?.78:.48;
  const outer=new T.Mesh(new T.CylinderGeometry(r+thickness,r+thickness,2.7,48,1,true),mat(0xed8b78,{side:T.DoubleSide}));outer.rotation.x=Math.PI/2;group.add(outer);for(const z of [-1.35,1.35]){const ring=new T.Mesh(new T.TorusGeometry(r+thickness/2,thickness/2,20,60),mat(0xed8b78));ring.position.z=z;group.add(ring);}if(w.valve==='yes')for(const x of [-.22,.22]){const flap=new T.Mesh(new T.BoxGeometry(.45,.9,.05),mat(0xd4dfe7,{side:T.DoubleSide}));flap.position.set(x,0,.6);flap.rotation.y=x<0?-.6:.6;group.add(flap);}return;
 }
 if(kind==='blood'){
  const on=w.on!==false,id=w.component||'red';if(id==='red'){const profile=[[0,-.09],[.28,-.11],[.6,-.25],[.85,-.13],[.9,0],[.85,.13],[.6,.25],[.28,.11],[0,.09]].map(([x,y])=>new T.Vector2(x,y));const cell=new T.Mesh(new T.LatheGeometry(profile,64),mat(on?0xca715f:0xb7c8d6));cell.rotation.x=.8;group.add(cell);}else if(id==='white'){const cell=new T.Mesh(new T.SphereGeometry(.95,40,28),mat(0xd4dfe7,{transparent:true,opacity:.6}));group.add(cell);for(let i=0;i<3;i++){const nucleus=new T.Mesh(new T.SphereGeometry(.3,28,20),mat(0x526575));nucleus.position.set((i-1)*.3,Math.sin(i*2)*.2,.7);group.add(nucleus);}const pathogen=new T.Mesh(new T.IcosahedronGeometry(.2,1),mat(0xca715f));pathogen.position.set(on?.35:1.45,on?.25:0,.4);group.add(pathogen);}else if(id==='platelet'){for(let i=0;i<6;i++){const m=new T.Mesh(new T.IcosahedronGeometry(.22,0),mat(on?0xca715f:0xb7c8d6));m.position.set((i%3-1)*(on?.22:.65),(Math.floor(i/3)-.5)*(on?.3:.8),0);m.rotation.set(i*.4,i*.7,i);group.add(m);}for(let x of [-1,1]){const wall=new T.Mesh(new T.BoxGeometry(1.3,.12,.2),mat(0xd4dfe7));wall.position.set(x*.9,-.3,-.1);group.add(wall);}}else{const fluid=new T.Mesh(new T.SphereGeometry(1.1,40,28),mat(0xd9bd7d,{transparent:true,opacity:on?.45:.1}));group.add(fluid);if(on)for(let i=0;i<12;i++){const m=new T.Mesh(new T.SphereGeometry(.07,16,12),mat(0xf8f6f2));m.position.set(Math.sin(i*2)*.8,Math.cos(i*3)*.8,Math.sin(i*5)*.5);group.add(m);}}return;
 }
 const r=w.area==='reduced'?.65:.95;const airSac=new T.Mesh(new T.SphereGeometry(r,40,28),mat(0xb7c8d6,{transparent:true,opacity:w.wall==='thick'?.7:.3}));group.add(airSac);for(let i=0;i<3;i++){const cap=new T.Mesh(new T.TorusGeometry(r+.1,.07,14,60),mat(w.blood==='off'?0x71808c:0xed8b78));cap.rotation.set(i*.9,.5+i*.6,.3);group.add(cap);}const neck=new T.Mesh(new T.CylinderGeometry(.25,.25,.9,28),mat(0xd4dfe7));neck.position.y=1.15;group.add(neck);if(w.air!=='off')for(let i=0;i<3;i++){const gas=new T.Mesh(new T.SphereGeometry(.07,14,10),mat(0xf8f6f2));gas.position.set((i-1)*.15,1.3,.2);group.add(gas);}
}
